@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/*
  Visual system: warm editorial mono.
  Warm-tinted neutrals (stone family), hairline dividers, Geist type doing
  the work. No chromatic accent in chrome — blue survives only inside the
  AI Activity heatmap. Identity from restraint, not hue.
*/
@theme {
  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, monospace;

  --color-background: #fafaf9;
  --color-background-muted: #f5f5f4;
  --color-foreground: #1c1917;
  --color-muted: #57534e;
  --color-faint: #8b8b88;
  --color-border: #e7e5e4;
  --color-border-strong: #d6d3d1;
  --color-surface: #ffffff;
  --color-surface-hover: #f5f5f4;
  --color-accent: #0070f3;
  --color-accent-muted: #3291ff;
  --color-link: #1c1917;

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-out-quad: cubic-bezier(0.25, 1, 0.5, 1);
  --ease-bounce: cubic-bezier(0.2, -0.25, 0, 1.6);
}

.dark {
  --color-background: #131312;
  --color-background-muted: #1c1c1a;
  --color-foreground: #e9e9e7;
  --color-muted: #a6a6a1;
  --color-faint: #767672;
  --color-border: #2a2a28;
  --color-border-strong: #3a3a37;
  --color-surface: #1c1c1a;
  --color-surface-hover: #232321;
  --color-accent: #3291ff;
  --color-accent-muted: #0070f3;
  --color-link: #e9e9e7;
}

@layer base {
  html {
    color-scheme: light;
    scroll-behavior: smooth;
  }

  html.dark {
    color-scheme: dark;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-feature-settings: "ss01" 1, "cv01" 1, "liga" 1, "calt" 1;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    background: var(--color-foreground);
    color: var(--color-background);
  }

  a {
    @apply text-link;
  }

  :focus-visible {
    outline: 2px solid var(--color-foreground);
    outline-offset: 3px;
  }
}

.skip-link {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link:focus {
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 50;
  width: auto;
  height: auto;
  margin: 0;
  clip: auto;
  overflow: visible;
  white-space: normal;
  border-radius: 0.5rem;
  background-color: var(--color-foreground);
  color: var(--color-background);
  padding: 0.5rem 0.75rem;
  font-size: 0.8125rem;
  font-weight: 500;
  outline: none;
}

.container-editorial {
  @apply mx-auto w-full max-w-[42rem] px-5 sm:px-6;
}

.container-wide {
  @apply mx-auto w-full max-w-[42rem] px-5 sm:px-6;
}

/* Type */
.display-title {
  @apply text-[2.25rem] font-medium leading-[1.05] tracking-[-0.045em] text-foreground text-pretty sm:text-[3rem];
}

.section-title {
  @apply text-[0.75rem] font-medium uppercase tracking-[0.2em] text-faint;
}

.body-copy {
  @apply text-[16px] leading-[1.7] text-muted text-pretty;
}

.meta-copy {
  @apply font-mono text-[12px] leading-4 tracking-[-0.01em] text-faint tabular-nums;
}

/* Links */
.link-editorial {
  @apply relative inline-flex min-h-9 items-center text-foreground no-underline;
  transition: color 160ms var(--ease-out-quad);
}

.link-editorial::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0.35rem;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 220ms var(--ease-out-expo);
}

.link-editorial:hover::after,
.link-editorial:focus-visible::after {
  transform: scaleX(1);
}

.link-editorial-muted {
  @apply inline-flex min-h-9 items-center text-muted no-underline;
  transition: color 160ms var(--ease-out-quad);
}

.link-editorial-muted:hover {
  color: var(--color-foreground);
}

/* Sections separate by whitespace only — hairlines belong to lists. */
.section-home {
  @apply mt-16;
}

/* Quiet status dot — ink pulse, functional not decorative. */
.status-dot {
  position: relative;
  display: inline-flex;
  border-radius: 9999px;
  background: currentColor;
}

.status-dot::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  background: currentColor;
  animation: ping-soft 2.4s var(--ease-out-quad) infinite;
}

@keyframes ping-soft {
  0% {
    transform: scale(1);
    opacity: 0.5;
  }
  70%,
  100% {
    transform: scale(2.8);
    opacity: 0;
  }
}

/* CV rows — divided editorial list (name → description → url ↗ → year).
   Identity from hairlines + ink shifts, no cards, no chrome. */
.cv-list {
  @apply border-t border-border;
}

.cv-row {
  @apply flex flex-col gap-x-4 gap-y-0.5 border-b border-border py-3.5 no-underline sm:flex-row sm:items-baseline sm:justify-between;
}

.cv-row-name {
  @apply shrink-0 text-[15px] font-medium tracking-[-0.01em] text-foreground underline-offset-[3px];
}

.cv-row:hover .cv-row-name,
.cv-row:focus-visible .cv-row-name {
  text-decoration-line: underline;
  text-decoration-thickness: 1px;
}

.cv-row-desc {
  @apply min-w-0 text-[13px] leading-5 text-muted transition-colors duration-150 sm:truncate;
}

.cv-row:hover .cv-row-desc,
.cv-row:focus-visible .cv-row-desc {
  color: var(--color-foreground);
}

.cv-row-meta {
  @apply flex shrink-0 items-baseline gap-3 whitespace-nowrap font-mono text-[12px] leading-4 tracking-[-0.01em] text-faint tabular-nums transition-colors duration-150 sm:justify-end;
}

.cv-row:hover .cv-row-meta,
.cv-row:focus-visible .cv-row-meta {
  color: var(--color-muted);
}

/* Entrance — quiet staggered rise. CSS-only, reduced-motion safe. */
@keyframes reveal {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.reveal {
  opacity: 0;
  animation: reveal 0.55s var(--ease-out-expo) forwards;
}

.reveal-delay-1 {
  animation-delay: 0.06s;
}
.reveal-delay-2 {
  animation-delay: 0.14s;
}
.reveal-delay-3 {
  animation-delay: 0.22s;
}

/* Project / writing rows — changelog energy */
.row-interactive {
  @apply relative -mx-3 rounded-md px-3 py-3 transition-[background-color,transform] duration-200;
  transition-timing-function: var(--ease-out-quad);
}

.row-interactive:hover {
  background: var(--color-surface-hover);
}

.row-interactive:active {
  transform: scale(0.997);
}

.row-arrow {
  @apply text-faint opacity-0 transition-[opacity,transform] duration-200;
  transition-timing-function: var(--ease-out-expo);
  transform: translateX(-4px);
}

.row-interactive:hover .row-arrow,
.row-interactive:focus-within .row-arrow {
  opacity: 1;
  transform: translateX(0);
}

/* MDX */
.prose-editorial {
  @apply text-[16px] leading-7 text-foreground;
}

.prose-editorial :where(p, ul, ol, blockquote, pre, table) {
  @apply my-5;
}

.prose-editorial :where(h2, h3, h4) {
  @apply mt-12 mb-3 font-semibold tracking-[-0.02em] text-foreground;
}

.prose-editorial h2 {
  @apply text-[1.375rem];
}

.prose-editorial h3 {
  @apply text-[1.125rem];
}

.prose-editorial :where(ul, ol) {
  @apply pl-5;
}

.prose-editorial ul {
  @apply list-disc;
}

.prose-editorial ol {
  @apply list-decimal;
}

.prose-editorial a {
  color: inherit;
  text-decoration-line: underline;
  text-decoration-color: color-mix(in srgb, currentColor 30%, transparent);
  text-underline-offset: 2px;
  transition: text-decoration-color 150ms var(--ease-out-quad);
}

.prose-editorial a:hover {
  text-decoration-color: color-mix(in srgb, currentColor 70%, transparent);
}

.prose-editorial a.anchor {
  text-decoration-line: none;
}

.prose-editorial :where(code):not(pre code) {
  @apply rounded-[4px] px-1.5 py-0.5 font-mono text-[0.84em];
  background: var(--color-background-muted);
  border: 1px solid var(--color-border);
}

.prose-editorial pre {
  @apply overflow-x-auto rounded-md border border-border p-4 font-mono text-[13px] leading-6;
  background: var(--color-background-muted);
}

.prose-editorial blockquote {
  @apply border-l-2 border-border-strong pl-4 text-muted;
}

.prose-editorial img {
  @apply my-6 h-auto w-full rounded-md;
}

/* AI Activity — Vercel analytics blue, not GitHub green */
.activity-cell {
  border-radius: 2px;
  transition:
    transform 120ms var(--ease-out-quad),
    box-shadow 120ms var(--ease-out-quad),
    opacity 120ms var(--ease-out-quad);
}

.activity-cell:hover,
.activity-cell:focus-visible {
  transform: scale(1.35);
  z-index: 1;
  box-shadow: 0 0 0 1px var(--color-background);
}

.activity-cell.intensity-0 {
  background-color: #eeeeec;
}

.activity-cell.intensity-1 {
  background-color: #c8e1ff;
}

.activity-cell.intensity-2 {
  background-color: #79b8ff;
}

.activity-cell.intensity-3 {
  background-color: #2188ff;
}

.activity-cell.intensity-4 {
  background-color: #0070f3;
}

.dark .activity-cell.intensity-0 {
  background-color: #1d1d1b;
  box-shadow: inset 0 0 0 1px #2a2a28;
}

.dark .activity-cell.intensity-1 {
  background-color: #0d419d;
}

.dark .activity-cell.intensity-2 {
  background-color: #0e64d8;
}

.dark .activity-cell.intensity-3 {
  background-color: #1f6feb;
}

.dark .activity-cell.intensity-4 {
  background-color: #58a6ff;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .link-editorial::after,
  .row-arrow,
  .activity-cell,
  .row-interactive {
    transition: none !important;
  }

  .reveal {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .status-dot::before {
    animation: none;
  }
}

