/* Command menu — one panel, no chrome beyond hairlines + type. */
.command-overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 16vh 1.25rem 1.25rem;
  background: color-mix(in srgb, var(--color-background) 62%, transparent);
  animation: command-fade 140ms var(--ease-out-quad);
}

.command-panel {
  width: min(92vw, 28rem);
  border-radius: 12px;
  border: 1px solid var(--color-border);
  background: var(--color-background);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--color-foreground) 4%, transparent),
    0 24px 70px -20px color-mix(in srgb, var(--color-foreground) 35%, transparent);
  animation: command-pop 180ms var(--ease-out-expo);
}

@keyframes command-fade {
  from {
    opacity: 0;
  }
}

@keyframes command-pop {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.985);
  }
}

.command-row {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  border-radius: 6px;
  padding: 0.5rem 0.75rem;
  text-align: left;
  font-size: 13px;
  color: var(--color-muted);
  transition:
    background-color 100ms var(--ease-out-quad),
    color 100ms var(--ease-out-quad);
}

.command-row-active {
  background: var(--color-background-muted);
  color: var(--color-foreground);
}

.kbd {
  display: inline-flex;
  min-height: 1.25rem;
  align-items: center;
  border-radius: 5px;
  border: 1px solid var(--color-border);
  background: var(--color-background-muted);
  padding: 0 0.375rem;
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1;
  color: var(--color-faint);
  text-transform: uppercase;
}

