/* Live today cell — soft ring pulse, signals the projection is moving */
.activity-cell-live {
  position: relative;
}

.activity-cell-live::after {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 3px;
  border: 1px solid color-mix(in srgb, var(--color-accent) 65%, transparent);
  animation: cell-ring 2.4s var(--ease-out-quad) infinite;
  pointer-events: none;
}

@keyframes cell-ring {
  0% {
    transform: scale(1);
    opacity: 0.9;
  }
  70%,
  100% {
    transform: scale(1.9);
    opacity: 0;
  }
}

/* Floating day tooltip — inverted ink, above the cell */
.activity-tooltip {
  position: fixed;
  z-index: 50;
  transform: translate(-50%, -100%);
  white-space: nowrap;
  border-radius: 6px;
  background: var(--color-foreground);
  color: var(--color-background);
  padding: 0.3rem 0.55rem;
  font-size: 11px;
  line-height: 1.35;
  font-family: var(--font-mono);
  letter-spacing: -0.01em;
  animation: command-fade 120ms var(--ease-out-quad);
  pointer-events: none;
}

.activity-tooltip::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -3px;
  width: 7px;
  height: 7px;
  transform: translateX(-50%) rotate(45deg);
  background: inherit;
  border-radius: 1px;
}

.activity-tooltip-faint {
  color: color-mix(in srgb, var(--color-background) 62%, transparent);
}

