agent-browser eval "(() => {
  const lum = c => { const s = c.map(v => { v/=255; return v<=0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055,2.4); }); return 0.2126*s[0]+0.7152*s[1]+0.0722*s[2]; };
  const rgb = el => getComputedStyle(el).color.match(/\d+\.?\d*/g).map(Number).slice(0,3);
  const bgOf = el => getComputedStyle(document.body).backgroundColor.match(/\d+\.?\d*/g).map(Number).slice(0,3);
  const ratio = (a,b) => { const l1=lum(a),l2=lum(b); return (Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05); };
  const fg = el => ratio(rgb(el), bgOf(el));
  const h1 = document.querySelector('h1');
  const muted = document.querySelector('.body-copy');
  const faint = document.querySelector('.meta-copy');
  const rowDesc = document.querySelector('.cv-row-desc');
  return {h1: +fg(h1).toFixed(2), body: +fg(muted).toFixed(2), meta: +fg(faint).toFixed(2), rowDesc: +fg(rowDesc).toFixed(2), theme: document.documentElement.className.includes('dark')};
})()" 2>&1

