  return {theme: document.documentElement.className.includes('dark') ? 'dark' : 'light', bg: bgc, lightH1: +ratio(h1c,bgc).toFixed(2), lightBody: +ratio(muted,bgc).toFixed(2), lightFaint: +ratio(meta,bgc).toFixed(2)};
})()" 2>&1 | tail -10

